export type Conteo = {
  llamadas: number
  input_tokens: number
  output_tokens: number
  cache_read_input_tokens: number
  cache_creation_input_tokens: number
  usd: number
}

export type FilaModelo = Conteo & { modelo: string }

export type FilaTarea = {
  titulo: string
  veces: number
  llamadas: number
  output_tokens: number
  cache_read_input_tokens: number
  cache_creation_input_tokens: number
  usd: number
  modelo: string
  /** Segundos desde la época del primer y último mensaje de la tarea, o null. */
  inicio: number | null
  fin: number | null
  minutos: number | null
  /** Solo en la tarea actual: minutos desde su última respuesta. */
  hace_min?: number | null
}

export type Despertador = {
  razon: string
  segundos: number | null
  parar: boolean
  noop: boolean
  cuando: number | null
  proximo?: number
  faltan_min?: number
}

export type Ritmo = {
  cubos_usd: number[]
  ancho_cubo_min: number
  usd_ultimos_30_min: number
  usd_por_hora: number
}

export type Resumen = {
  transcripcion: string
  /** La sesión acaba de abrirse y el motor aún no escribió la transcripción: el resumen va vacío. */
  sin_transcripcion?: boolean
  ahora: number
  inicio_sesion: number | null
  ultima_respuesta: number | null
  total: Conteo
  por_modelo: FilaModelo[]
  por_tarea: FilaTarea[]
  por_herramienta: Record<string, number>
  subagentes: string[]
  actual: FilaTarea | null
  despertador: Despertador | null
  ritmo: Ritmo
  nota_precios: string
}

export type Cobertura = {
  /** Porcentaje total de líneas cubiertas, o null si no hay dato. */
  total: number | null
  /** 'lista' | 'corriendo' | 'sin-dato' | 'no-aplica' | 'error' */
  estado: string
  /** Hora de la última medición o intento, en milisegundos. */
  cuando: number | null
  /** Última línea útil de la herramienta, recortada. */
  nota: string
}

export type Sesion = {
  /** Costo según el libro del propio motor (/cost), en USD; null si no lo da. */
  usdMotor: number | null
  /** Porcentaje del contexto ocupado, o null. */
  contextoPct: number | null
  /** Tokens del contexto en la última respuesta, o null. */
  contextoTokens: number | null
  /** Tamaño de la ventana de contexto en tokens, o null. */
  ventana: number | null
  /** Cuándo empezó la sesión, en milisegundos, o null. */
  inicio: number | null
  /** Hora de la última actualización, en milisegundos. */
  actualizado: number | null
  /** Error de la última actualización, o ''. */
  error: string
}

export type IssueGitHub = { number: number; title: string; labels: string[]; updatedAt: string }
export type PrGitHub = { number: number; title: string; isDraft: boolean; updatedAt: string }

export type GitHub = {
  repo: string
  cuando: number | null
  issues: IssueGitHub[]
  prs: PrGitHub[]
  error: string
}

export type SemanaAvance = {
  /** Lunes de la semana, AAAA-MM-DD (UTC). */
  lunes: string
  creadas: number
  /** Issues cerradas como hechas esa semana, sin contar las descartadas. */
  hechas: number
  descartadas: number
  /** Issues abiertas al terminar la semana. */
  abiertas_fin: number
  /** Parte de la factura mensual que el proyecto consumió esa semana, en USD. */
  usd_factura: number
  /** Porcentaje del consumo del proyecto en la ventana que cayó en esa semana. */
  pct_del_proyecto: number
}

export type ProyectoAvance = {
  /** Carpeta del proyecto en ~/.claude/projects, en minúsculas y con sus worktrees sumados. */
  clave: string
  sesiones: number
  prompts: number
  llamadas: number
  /** Parte del consumo de todos los proyectos de esta máquina, en porcentaje. */
  pct_del_total: number
  /** Esa parte aplicada a la factura mensual, en USD. */
  usd_factura: number
  pct_subagentes: number
  /** Porcentaje del consumo que es releer contexto (caché leída). */
  pct_relectura: number
  despertares: number
  /** Despertares del bucle que terminaron sin cambiar nada (noop). */
  despertares_vacios: number
  agentes: number
}

export type RepoAvance = {
  nombre: string
  /** Con qué cuenta de gh se leyó. */
  via: string
  error: string
  abiertas: number
  creadas: number
  hechas: number
  descartadas: number
  /** Parte de la factura del proyecto dividida entre las issues cerradas, o null si no hubo. */
  usd_por_issue: number | null
}

export type Avance = {
  /** 'sin-dato' | 'midiendo' | 'lista' | 'error' */
  estado: string
  /** Hora de la última medición o intento, en milisegundos. */
  cuando: number | null
  error: string
  /** Primer día de la ventana medida, AAAA-MM-DD, o ''. */
  desde: string
  /** Factura mensual sobre la que se reparte, en USD. */
  factura: number
  proyecto: ProyectoAvance | null
  repo: RepoAvance | null
  semanas: SemanaAvance[]
  /** Los proyectos de esta máquina que entran en el reparto. `raiz`: su carpeta, o '' si no se pudo deducir. */
  reparto: { nombre: string; pct: number; usd: number; raiz?: string }[]
  /** Ruta del index de tareas (privado) que se escribió al medir, o '' si no se escribió. */
  index: string
}

/** La última decisión del control, en frases: quién tiene cada issue y qué hará el próximo despertar. */
export type Control = {
  cuando: number | null
  /** false: el repositorio de trabajo no tiene .claude/orquestacion.json y el control no decide en él. */
  activo: boolean
  /** «ok» o por qué no se pudieron leer las issues. */
  github: string
  /** Quién tiene tomado el candado de suites, o vacío. */
  candado: string
  frases: string[]
  resto: string[]
  avisos: string[]
  /** La orden del próximo despertar de esta sesión, con las cifras de la última foto: es la que pinta el panel. */
  orden: string
  /**
   * La misma orden tal como quedó la última vez que CAMBIÓ (cambiaron las señales que mandan, no la hora): es la
   * que va al prompt de sistema, para no romper su caché en cada foto.
   */
  ordenPrompt: string
  /** Qué señales mandan, sin horas ni duraciones. */
  firma: string
  /** Cuántas señales del index cambian la orden (0: la orden de siempre). */
  causas: number
}

/** Una señal del index (un cuello de botella), como la lee el control. */
export type SenalDelIndex = { tipo: string; gravedad: 'alta' | 'media'; que: string; desde?: string; datos?: Record<string, unknown> }

/** Lo que el panel y el control leen de index.json y diario.json. Con la foto vieja, `vigente` es false y todo va vacío. */
export type Lectura = {
  /** false: no hay index.json que leer. */
  instalado: boolean
  /** La foto tiene diez minutos o menos. */
  vigente: boolean
  foto_ms: number | null
  /** El repositorio del index que corresponde a esta sesión, o null si esta carpeta no está en él. */
  repositorio: string | null
  senales: SenalDelIndex[]
  /** Los números de las issues abiertas, o null si GitHub no se midió. */
  abiertas: number[] | null
  fuera: string[]
  /** Issues que lo declarado da por asignadas y lo medido contradice. */
  caducadas: number[]
  /** Issues construidas (con algún commit que las nombra), del cálculo diario; null si no lo hay. */
  construidas: number | null
  primera_alta: string | null
  foto: string
  /** El aviso de foto vieja, o de que esta carpeta no está en el index. */
  vieja: string
  cuellos: { gravedad: string; texto: string }[]
  cuellos_resto: string
  quien_titulo: string
  quien: string[]
  declarado: string[]
  flujo: string[]
  coordinacion: string[]
}

/** El index vivo: lo que dejó la última corrida del guion sin modelo (herramientas/indice.mjs), si está instalado. */
export type Vivo = {
  /** null: todavía no se miró. false: el guion no está instalado en la carpeta del index. */
  instalado: boolean | null
  /** La carpeta del index, o '' si no se pudo deducir. */
  carpeta: string
  /** El primer cuello de botella, en una línea, o '' si no hay ninguno. */
  cuello: string
  cuellos: number
  /** Los cuellos de gravedad alta de la última foto: sirven para avisar sólo de los nuevos. */
  altas: string[]
  cuando: number | null
  /** La última foto leída, ya en líneas para el panel. */
  lectura: Lectura
}

declare module 'claude-code' {
  interface PluginState {
    consumo: {
      avance: Avance
      resumen: Resumen | null
      cobertura: Cobertura
      sesion: Sesion
      github: GitHub
      control: Control
      vivo: Vivo
    }
  }
}
